function IsSumOfMSquares(m, n):
    if n < 0: return False
    if m == 0: return n == 0
    if m >= 4: return True            # Lagrange + padding: S_m = N
    squares <- [ s*s for s in 0..floor(sqrt(n)) ]
    reachable <- { 0 }
    repeat m times:
        next <- {}
        for v in reachable:
            for sq in squares:
                if v + sq <= n: add v+sq to next
        reachable <- next
    return (n in reachable)

function RepresentationSet(m, upper):
    if m >= 4: return [0 .. upper]
    return [ n in 0..upper : IsSumOfMSquares(m, n) ]

